function sumarBulto(p) {
  p.bultos = p.bultos + 1;       // muta el objeto al que apunta la referencia
}
function reemplazar(p) {
  p = { cliente: "otro", bultos: 100 };   // cambia solo la copia local de la referencia
}
function sumarUno(n) {
  n = n + 1;                      // cambia solo la copia local del número
  return n;
}

const pedido = { cliente: "Kiosco Norte", bultos: 3 };
sumarBulto(pedido);
console.log("después de sumarBulto:", JSON.stringify(pedido));
reemplazar(pedido);
console.log("después de reemplazar:", JSON.stringify(pedido));

