#include <stdio.h>

struct Pedido { char cliente[16]; int bultos; };

static void sumar_valor(struct Pedido p)    { p.bultos += 1; }     /* recibe una copia entera */
static void sumar_puntero(struct Pedido *p) { p->bultos += 1; }    /* recibe la dirección */

int main(void) {
    struct Pedido a = { "Kiosco Norte", 3 };
    struct Pedido b = a;            /* copia los bytes del struct */
    b.bultos = 9;
    printf("a.bultos = %d, b.bultos = %d\n", a.bultos, b.bultos);

    sumar_valor(a);
    printf("tras sumar_valor:   %d\n", a.bultos);
    sumar_puntero(&a);
    printf("tras sumar_puntero: %d\n", a.bultos);

    struct Pedido *q = &a;          /* un alias explícito: otra dirección al mismo struct */
    q->bultos = 50;
    printf("a.bultos = %d (q apunta a a: %s)\n", a.bultos, q == &a ? "sí" : "no");
    printf("sizeof(struct Pedido) = %zu bytes, sizeof(struct Pedido *) = %zu bytes\n", sizeof(struct Pedido), sizeof(struct Pedido *));
    return 0;
}

